structure.mermaidSource:
flowchart TD
  start["Início: Identificar verbo principal e auxiliar na locução"] --> dec_excecoes{"O verbo é GANHAR, GASTAR, PEGAR ou PAGAR?"}
  dec_excecoes -- "Sim" --> res_vale_tudo["Regra do Vale Tudo: Usar livremente forma regular ou irregular"]
  dec_excecoes -- "Não" --> dec_abundante{"O verbo é abundante no particípio?"}
  dec_abundante -- "Não" --> res_unica_forma["Usar forma única existente na norma culta"]
  dec_abundante -- "Sim" --> dec_auxiliar{"Qual é o verbo auxiliar da locução?"}
  dec_auxiliar -- "TER ou HAVER" --> res_regular["Usar Particípio Regular terminado em -DO"]
  dec_auxiliar -- "SER ou ESTAR" --> res_irregular["Usar Particípio Irregular forma curta"]

flowchart TD
  start["Início: Isolar Gerúndio e Oração Principal"] --> dec_tempo{"Troca por 'Quando / Assim que' mantém o sentido?"}
  dec_tempo -- "Sim" --> res_tempo["Valor Semântico: TEMPO"]
  dec_tempo -- "Não" --> dec_causa{"Troca por 'Porque / Visto que' indica causa?"}
  dec_causa -- "Sim" --> res_causa["Valor Semântico: CAUSA"]
  dec_causa -- "Não" --> dec_conseq{"Troca por 'De modo que' indica efeito?"}
  dec_conseq -- "Sim" --> res_conseq["Valor Semântico: CONSEQUÊNCIA"]
  dec_conseq -- "Não" --> dec_adicao{"Troca por 'e + verbo' adiciona fato subsequente?"}
  dec_adicao -- "Sim" --> res_adicao["Valor Semântico: ADIÇÃO / CONSEQUÊNCIA"]
  dec_adicao -- "Não" --> res_outros["Avaliar Outros Valores (Condição, Concessão, Modo)"]
